"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["43723"],{77676(e){e.exports=JSON.parse('{"id":"F350","slug":"cva-approximation","name":"Credit Valuation Adjustment (CVA)","subject":"Derivatives","section":"Derivatives","topic":"Central clearing and counterparty risk","level":"Intermediate","aliases":["counterparty credit risk","expected exposure","OTC derivatives credit charge","bilateral risk"],"formula":{"latex":"CVA=(1-R)\\\\sum_{t}EE_{t}\\\\,PD_{t}\\\\,DF_{t}","also":[],"text":"CVA = (1 - Recovery) x Sum over each year of [Expected positive exposure x Probability of default in that year x Discount factor]"},"symbols":[{"symbol":"R","meaning":"Recovery rate on the claim against the counterparty","unit":"percent"},{"symbol":"EE_t","meaning":"Expected positive exposure in year t: the average amount the counterparty would owe if it defaulted then","unit":"money"},{"symbol":"PD_t","meaning":"Probability the counterparty defaults in year t, after surviving earlier years","unit":"per year"},{"symbol":"DF_t","meaning":"Discount factor for year t","unit":"number"}],"when_to_use":"Use it to price the risk that the other side of an over-the-counter derivative fails to pay. CVA is the expected loss from counterparty default, and banks deduct it from the value of their derivatives. Central clearing reduces this risk by guaranteeing the trades.","worked_example":{"problem":"A bank\'s expected exposure to a counterparty over the next five years is 2, 3, 3.5, 3 and 2 million. The counterparty has a 1.5% annual default probability, a 40% recovery and the discount rate is 3%. What is the CVA?","inputs":{"ee":[2,3,3.5,3,2],"pd":1.5,"r":40,"dr":3},"steps":[{"label":"Probability of default in each year = PD x (1 - PD)^(t - 1)","working":null,"value":"0.0150, 0.0148, 0.0146, 0.0143, 0.0141"},{"label":"Discount factor for each year","working":null,"value":"0.9709, 0.9426, 0.9151, 0.8885, 0.8626"},{"label":"Exposure x probability x discount factor for each year","working":null,"value":"0.0291, 0.0418, 0.0466, 0.0382, 0.0244"},{"label":"CVA = (1 - R) x sum","working":null,"value":"0.1081"}],"answer":"The CVA is 0.1081 million. That is the amount by which the derivatives\' value is reduced to allow for the chance that the counterparty does not pay."},"calculator":{"available":true,"inputs":[{"id":"ee","label":"Expected exposure by year (millions)","unit":"money","type":"list","default":[2,3,3.5,3,2],"hint":""},{"id":"pd","label":"Annual default probability","unit":"%","type":"number","default":1.5,"hint":""},{"id":"r","label":"Recovery rate","unit":"%","type":"number","default":40,"hint":""},{"id":"dr","label":"Discount rate","unit":"%","type":"number","default":3,"hint":""}],"checks":[{"expr":"count(ee)>=1 and pd<1 and r<1","message":"Enter at least one exposure; the default probability and recovery must be below 100%."}],"steps":[{"id":"marg","label":"Probability of default in each year = PD x (1 - PD)^(t - 1)","expr":"scale(geom(1-pd, count(ee)), pd/(1-pd))","format":"list4"},{"id":"dfs","label":"Discount factor for each year","expr":"geom(1/(1+dr), count(ee))","format":"list4"},{"id":"terms","label":"Exposure x probability x discount factor for each year","expr":"multiply(multiply(ee, marg), dfs)","format":"list4"},{"id":"cva","label":"CVA = (1 - R) x sum","expr":"(1-r)*sum(terms)","format":"num4"}],"results":["cva"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"cva":0.10805454926772874}},"finder":{"finds":"The expected loss from a derivative counterparty\'s default","needs":"Expected exposures, default probability, recovery, discount rate"},"related":[{"slug":"ccp-initial-margin","name":"Central Counterparty Initial Margin (Value-at-Risk Method)"},{"slug":"default-probability-from-spread","name":"Default Probability and Recovery from Credit Spread"},{"slug":"cds-spread-upfront","name":"Credit Default Swap: Spread, Upfront and Payout"}],"related_ids":["F349","F302","F344"],"group":"Markets and instruments","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>C</mi><mi>V</mi><mi>A</mi><mo>=</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>R</mi><mo stretchy=\\"false\\">)</mo><munder><mo>\u2211</mo><mi>t</mi></munder><mi>E</mi><msub><mi>E</mi><mi>t</mi></msub><mtext>\u2009</mtext><mi>P</mi><msub><mi>D</mi><mi>t</mi></msub><mtext>\u2009</mtext><mi>D</mi><msub><mi>F</mi><mi>t</mi></msub></mrow><annotation encoding=\\"application/x-tex\\">CVA=(1-R)\\\\sum_{t}EE_{t}\\\\,PD_{t}\\\\,DF_{t}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"credit-utilization","name":"Credit Utilization Ratio"},"next":{"slug":"triangular-arbitrage","name":"Cross Rates and Triangular Arbitrage"},"lesson":null,"total":522}')}}]);